/*
  Seed: Tehran neighborhoods and exact polygon boundaries
  Generated from OpenStreetMap / Overpass at 2026-08-16T10:54:51Z
  License: Open Database License (ODbL) - https://www.openstreetmap.org/copyright
  SRID: 4326 (longitude latitude)
  OSM boundary parts: 370
  Unique neighborhood rows: 369
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @TehranCityId bigint;

    SELECT TOP (1)
        @TehranCityId = city.[Id]
    FROM dbo.[Cities] AS city
    INNER JOIN dbo.[States] AS state ON state.[Id] = city.[StateId]
    WHERE REPLACE(REPLACE(LTRIM(RTRIM(city.[Name])), N'ي', N'ی'), N'ك', N'ک') = N'تهران'
    ORDER BY CASE WHEN REPLACE(REPLACE(LTRIM(RTRIM(state.[Name])), N'ي', N'ی'), N'ك', N'ک') = N'تهران' THEN 0 ELSE 1 END, city.[Id];

    IF @TehranCityId IS NULL
        THROW 51000, N'شهر تهران در جدول Cities پیدا نشد.', 1;

    CREATE TABLE #TehranNeighborhoodPart
    (
        [Name] nvarchar(250) NOT NULL,
        [RegionNumber] int NOT NULL,
        [BoundaryWkt] nvarchar(max) NOT NULL,
        [SourceId] bigint NOT NULL
    );




















    -- OSM relation 9167435 has the Persian label of the western neighborhood,
    -- while its English label and eastern geometry identify it as East Lashkar.
    UPDATE #TehranNeighborhoodPart
    SET [Name] = N'لشکر شرقی'
    WHERE [SourceId] = 9167435;

    CREATE TABLE #TehranNeighborhoodSeed
    (
        [Name] nvarchar(250) NOT NULL,
        [RegionNumber] int NOT NULL,
        [Boundary] geography NOT NULL
    );

    SELECT
        part.[Name],
        part.[RegionNumber],
        geography::UnionAggregate(geography::STGeomFromText(part.[BoundaryWkt], 4326).MakeValid())
    FROM #TehranNeighborhoodPart AS part
    GROUP BY part.[Name], part.[RegionNumber];

    UPDATE neighborhood
    SET
        neighborhood.[Boundary] = seed.[Boundary]
    FROM dbo.[Neighborhoods] AS neighborhood
    INNER JOIN #TehranNeighborhoodSeed AS seed
        ON seed.[RegionNumber] = neighborhood.[RegionNumber]
        AND REPLACE(REPLACE(LTRIM(RTRIM(seed.[Name])), N'ي', N'ی'), N'ك', N'ک') = REPLACE(REPLACE(LTRIM(RTRIM(neighborhood.[Name])), N'ي', N'ی'), N'ك', N'ک')
    WHERE neighborhood.[CityId] = @TehranCityId;

    SELECT
        seed.[Name],
        seed.[RegionNumber],
        @TehranCityId,
        seed.[Boundary]
    FROM #TehranNeighborhoodSeed AS seed
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.[Neighborhoods] AS neighborhood
        WHERE neighborhood.[CityId] = @TehranCityId
          AND neighborhood.[RegionNumber] = seed.[RegionNumber]
          AND REPLACE(REPLACE(LTRIM(RTRIM(neighborhood.[Name])), N'ي', N'ی'), N'ك', N'ک') = REPLACE(REPLACE(LTRIM(RTRIM(seed.[Name])), N'ي', N'ی'), N'ك', N'ک')
    );

    IF EXISTS
    (
        SELECT 1
        FROM dbo.[Neighborhoods] AS neighborhood
        INNER JOIN #TehranNeighborhoodSeed AS seed
            ON seed.[RegionNumber] = neighborhood.[RegionNumber]
            AND REPLACE(REPLACE(LTRIM(RTRIM(seed.[Name])), N'ي', N'ی'), N'ك', N'ک') = REPLACE(REPLACE(LTRIM(RTRIM(neighborhood.[Name])), N'ي', N'ی'), N'ك', N'ک')
        WHERE neighborhood.[CityId] = @TehranCityId
          AND (neighborhood.[Boundary] IS NULL OR neighborhood.[Boundary].STIsValid() = 0)
    )
        THROW 51001, N'یک یا چند محدوده محله نامعتبر است.', 1;

    COMMIT TRANSACTION;

    SELECT
        @TehranCityId AS [TehranCityId],
        COUNT_BIG(*) AS [NeighborhoodCount]
    FROM dbo.[Neighborhoods]
    WHERE [CityId] = @TehranCityId;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
